fn can_stack_items(item_id1: Int, count1: Int, max_stack1: Int, item_id2: Int, count2: Int) -> Bool
    requires {
        count1 >= 0,
        count2 >= 0,
        max_stack1 > 0,
    }
    ensures {
        result == (item_id1 == item_id2 && count1 < max_stack1),
    }
{
    item_id1 == item_id2 && count1 < max_stack1
}

fn calc_stacked_counts(count1: Int, count2: Int, max_stack: Int) -> Int
    requires {
        count1 >= 0,
        count1 <= 1000000,
        count2 >= 0,
        count2 <= 1000000,
        max_stack > 0,
        max_stack <= 1000000,
    }
    ensures {
        result >= 0,
        result <= max_stack,
        count1 + count2 > max_stack => result == max_stack,
        count1 + count2 <= max_stack => result == count1 + count2,
    }
{
    match count1 + count2 > max_stack { true => max_stack, false => count1 + count2 }
}

fn calculate_purchase_cost(unit_price: Int, quantity: Int, discount_pct: Int) -> Int
    requires {
        unit_price >= 0,
        unit_price <= 100000000,
        quantity >= 0,
        quantity <= 100000,
        discount_pct >= 0,
        discount_pct <= 100,
    }
    ensures {
        result >= 0,
        result <= unit_price * quantity,
        discount_pct == 0 => result == unit_price * quantity,
        discount_pct == 100 => result == 0,
    }
{
    unit_price * quantity * (100 - discount_pct) / 100
}

fn validate_trade_balance(buyer_gold: Int, total_cost: Int, free_slots: Int, needed_slots: Int) -> Bool
    requires {
        buyer_gold >= 0,
        total_cost >= 0,
        free_slots >= 0,
        needed_slots >= 0,
    }
    ensures {
        result == (buyer_gold >= total_cost && free_slots >= needed_slots),
    }
{
    buyer_gold >= total_cost && free_slots >= needed_slots
}

fn calc_sell_refund(cost: Int, durability_cur: Int, durability_max: Int) -> Int
    requires {
        cost >= 0,
        cost <= 100000000,
        durability_max > 0,
        durability_max <= 100000,
        durability_cur >= 0,
        durability_cur <= durability_max,
    }
    ensures {
        result >= 0,
        result <= cost,
        durability_cur == durability_max => result == cost,
        durability_cur == 0 => result == 0,
    }
{
    match durability_cur == durability_max { true => cost, false => 0 }
}

